#include <stdio.h>

void solve_hanoi(int n, char from, char to, char aux) {
    if (n == 1) {
        printf("Move disk 1 from %c to %c
", from, to);
        return;
    }
    solve_hanoi(n - 1, from, aux, to);
    printf("Move disk %d from %c to %c
", n, from, to);
    solve_hanoi(n - 1, aux, to, from);
}

int main(void) {
    int disks = 3;
    printf("Solving Tower of Hanoi for %d disks:
", disks);
    solve_hanoi(disks, 'A', 'C', 'B');
    return 0;
}

#include <stdio.h>

long long memo[100];

long long fib(int n) {
    if (n <= 0) return 0;
    if (n == 1) return 1;
    if (memo[n] != 0) return memo[n];
    memo[n] = fib(n - 1) + fib(n - 2);
    return memo[n];
}

int main(void) {
    for (int i = 0; i <= 20; i++) {
        printf("Fib(%d) = %lld
", i, fib(i));
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

void reverse_string(char* str) {
    if (!str) return;
    char* start = str;
    char* end = str + strlen(str) - 1;
    while (start < end) {
        char temp = *start;
        *start = *end;
        *end = temp;
        start++;
        end--;
    }
}

int main(void) {
    char text[] = "Modern C Language";
    printf("Original: %s
", text);
    reverse_string(text);
    printf("Reversed: %s
", text);
    return 0;
}

