typedef struct Point {
    double x;
    double y;
} Point;

typedef struct Rect {
    Point top_left;
    Point bottom_right;
} Rect;

double rect_area(const Rect* r) {
    double width = r->bottom_right.x - r->top_left.x;
    double height = r->top_left.y - r->bottom_right.y;
    return width * height;
}

int main(void) {
    Rect r = {{0.0, 10.0}, {15.0, 0.0}};
    printf("Rectangle Top-Left: (%.1f, %.1f)
", r.top_left.x, r.top_left.y);
    printf("Rectangle Bottom-Right: (%.1f, %.1f)
", r.bottom_right.x, r.bottom_right.y);
    printf("Rectangle Area: %.2f
", rect_area(&r));
    return 0;
}

