int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <filename>
", argv[0]);
        return 1;
    }

    FILE* f = fopen(argv[1], "r");
    if (!f) {
        perror("Error opening file");
        return 1;
    }

    long lines = 0, words = 0, chars = 0;
    int c;
    bool in_word = false;

    while ((c = fgetc(f)) != EOF) {
        chars++;
        if (c == '
') lines++;
        if (isspace(c)) {
            in_word = false;
        } else if (!in_word) {
            in_word = true;
            words++;
        }
    }

    fclose(f);
    printf("File: %s
Lines: %ld | Words: %ld | Chars: %ld
", argv[1], lines, words, chars);
    return 0;
}

