Database* db_create(size_t initial_cap) {
    Database* db = (Database*)malloc(sizeof(Database));
    if (!db) return NULL;
    db->students = (Student*)malloc(initial_cap * sizeof(Student));
    if (!db->students) { free(db); return NULL; }
    db->count = 0;
    db->capacity = initial_cap;
    return db;
}

void db_add(Database* db, int id, const char* name, float marks) {
    if (db->count >= db->capacity) {
        size_t new_cap = db->capacity * 2;
        Student* next = (Student*)realloc(db->students, new_cap * sizeof(Student));
        if (!next) return;
        db->students = next;
        db->capacity = new_cap;
    }
    Student* s = &db->students[db->count++];
    s->id = id;
    strncpy(s->name, name, sizeof(s->name) - 1);
    s->name[sizeof(s->name) - 1] = '�';
    s->marks = marks;
}

void db_display(const Database* db) {
    printf("=== Student Records (%zu Total) ===
", db->count);
    for (size_t i = 0; i < db->count; i++) {
        printf("ID: %04d | Name: %-16s | Marks: %.1f
",
               db->students[i].id, db->students[i].name, db->students[i].marks);
    }
}

void db_free(Database* db) {
    if (!db) return;
    free(db->students);
    free(db);
}

int main(void) {
    Database* db = db_create(2);
    if (!db) return 1;

    db_add(db, 101, "Alice Miller", 88.5f);
    db_add(db, 102, "Brian Clark", 92.0f);
    db_add(db, 103, "Catherine Davis", 95.5f);

    db_display(db);
    db_free(db);
    return 0;
}

#include <stdio.h>
#include <string.h>

typedef enum TxType {
    TX_DEPOSIT,
    TX_WITHDRAWAL
} TxType;

typedef struct Transaction {
    int id;
    TxType type;
    double amount;
    char note[32];
} Transaction;

typedef struct Account {
    int account_number;
    char holder[48];
    double balance;
    Transaction history[20];
    int tx_count;
} Account;

int account_deposit(Account* acc, double amount, const char* note) {
    if (amount <= 0 || acc->tx_count >= 20) return 0;
    acc->balance += amount;
    Transaction* tx = &acc->history[acc->tx_count++];
    tx->id = acc->tx_count;
    tx->type = TX_DEPOSIT;
    tx->amount = amount;
    strncpy(tx->note, note, sizeof(tx->note) - 1);
    tx->note[sizeof(tx->note) - 1] = '�';
    return 1;
}

int account_withdraw(Account* acc, double amount, const char* note) {
    if (amount <= 0 || amount > acc->balance || acc->tx_count >= 20) return 0;
    acc->balance -= amount;
    Transaction* tx = &acc->history[acc->tx_count++];
    tx->id = acc->tx_count;
    tx->type = TX_WITHDRAWAL;
    tx->amount = amount;
    strncpy(tx->note, note, sizeof(tx->note) - 1);
    tx->note[sizeof(tx->note) - 1] = '�';
    return 1;
}

void account_statement(const Account* acc) {
    printf("=== Account Statement: #%d (%s) ===
", acc->account_number, acc->holder);
    printf("Current Balance: $%.2f
", acc->balance);
    printf("Transaction History (%d items):
", acc->tx_count);
    for (int i = 0; i < acc->tx_count; i++) {
        const Transaction* tx = &acc->history[i];
        printf("  #%d | %-10s | $%8.2f | %s
",
               tx->id, (tx->type == TX_DEPOSIT ? "DEPOSIT" : "WITHDRAW"), tx->amount, tx->note);
    }
}

int main(void) {
    Account acc = { .account_number = 50012, .holder = "James Wilson", .balance = 1000.0, .tx_count = 0 };
    account_deposit(&acc, 250.0, "Salary Bonus");
    account_withdraw(&acc, 120.0, "Groceries");
    account_withdraw(&acc, 45.0, "Utility Bill");
    account_statement(&acc);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct StringBuilder {
    char* data;
    size_t length;
    size_t capacity;
} StringBuilder;

StringBuilder* sb_create(void) {
    StringBuilder* sb = (StringBuilder*)malloc(sizeof(StringBuilder));
    if (!sb) return NULL;
    sb->capacity = 16;
    sb->length = 0;
    sb->data = (char*)malloc(sb->capacity);
    if (!sb->data) { free(sb); return NULL; }
    sb->data[0] = '�';
    return sb;
}

void sb_append(StringBuilder* sb, const char* str) {
    size_t str_len = strlen(str);
    while (sb->length + str_len + 1 > sb->capacity) {
        sb->capacity *= 2;
        char* next = (char*)realloc(sb->data, sb->capacity);
        if (!next) return;
        sb->data = next;
    }
    memcpy(sb->data + sb->length, str, str_len);
    sb->length += str_len;
    sb->data[sb->length] = '�';
}

void sb_free(StringBuilder* sb) {
    if (!sb) return;
    free(sb->data);
    free(sb);
}

int main(void) {
    StringBuilder* sb = sb_create();
    if (!sb) return 1;

    sb_append(sb, "SELECT id, name, score ");
    sb_append(sb, "FROM users ");
    sb_append(sb, "WHERE score >= 80 ");
    sb_append(sb, "ORDER BY score DESC;");

    printf("Constructed Query: %s
", sb->data);
    printf("Length: %zu, Capacity: %zu
", sb->length, sb->capacity);

    sb_free(sb);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <stdbool.h>

typedef struct FileStats {
    long lines;
    long words;
    long bytes;
} FileStats;

int analyze_file(const char* filepath, FileStats* stats) {
    FILE* f = fopen(filepath, "r");
    if (!f) return 0;

    stats->lines = 0;
    stats->words = 0;
    stats->bytes = 0;

    int c;
    bool in_word = false;
    while ((c = fgetc(f)) != EOF) {
        stats->bytes++;
        if (c == '
') stats->lines++;
        if (isspace(c)) {
            in_word = false;
        } else if (!in_word) {
            in_word = true;
            stats->words++;
        }
    }
    fclose(f);
    return 1;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <file1> [file2 ...]
", argv[0]);
        return 1;
    }

    printf("%-20s %8s %8s %8s
", "File", "Lines", "Words", "Bytes");
    printf("--------------------------------------------------
");

    for (int i = 1; i < argc; i++) {
        FileStats stats;
        if (analyze_file(argv[i], &stats)) {
            printf("%-20s %8ld %8ld %8ld
", argv[i], stats.lines, stats.words, stats.bytes);
        } else {
            printf("%-20s [ERROR: cannot open file]
", argv[i]);
        }
    }
    return 0;
}

