#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define STACK_CAPACITY 64

typedef struct Stack {
    int data[STACK_CAPACITY];
    int top;
} Stack;

void stack_init(Stack* s) { s->top = -1; }
int stack_push(Stack* s, int val) {
    if (s->top >= STACK_CAPACITY - 1) return 0;
    s->data[++s->top] = val;
    return 1;
}
int stack_pop(Stack* s, int* val) {
    if (s->top < 0) return 0;
    *val = s->data[s->top--];
    return 1;
}

int evaluate_postfix(const char* expr) {
    Stack stack;
    stack_init(&stack);

    const char* p = expr;
    while (*p != '�') {
        if (isspace(*p)) {
            p++;
            continue;
        }
        if (isdigit(*p)) {
            int val = 0;
            while (isdigit(*p)) {
                val = val * 10 + (*p - '0');
                p++;
            }
            stack_push(&stack, val);
        } else {
            int b, a;
            stack_pop(&stack, &b);
            stack_pop(&stack, &a);
            int res = 0;
            switch (*p) {
                case '+': res = a + b; break;
                case '-': res = a - b; break;
                case '*': res = a * b; break;
                case '/': res = (b != 0) ? a / b : 0; break;
            }
            stack_push(&stack, res);
            p++;
        }
    }

    int result = 0;
    stack_pop(&stack, &result);
    return result;
}

int main(void) {
    const char* expression = "15 7 1 1 + - / 3 * 2 1 1 + + -";
    printf("Postfix Expression: %s
", expression);
    printf("Evaluation Result: %d
", evaluate_postfix(expression));
    return 0;
}

