#include <stdio.h>
#include <stdarg.h>
#include <time.h>

typedef enum Level { LVL_DEBUG, LVL_INFO, LVL_WARN, LVL_ERROR } Level;

typedef struct Logger {
    Level min_level;
    const char* log_file;
} Logger;

void logger_write(const Logger* log, Level lvl, const char* fmt, ...) {
    if (lvl < log->min_level) return;

    const char* tags[] = {"DEBUG", "INFO", "WARN", "ERROR"};
    time_t now = time(NULL);
    char time_str[24];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&now));

    va_list args1, args2;
    va_start(args1, fmt);
    va_copy(args2, args1);

    printf("[%s] [%s] ", time_str, tags[lvl]);
    vprintf(fmt, args1);
    putchar('
');
    va_end(args1);

    if (log->log_file) {
        FILE* f = fopen(log->log_file, "a");
        if (f) {
            fprintf(f, "[%s] [%s] ", time_str, tags[lvl]);
            vfprintf(f, fmt, args2);
            fputc('
', f);
            fclose(f);
        }
    }
    va_end(args2);
}

int main(void) {
    Logger logger = { .min_level = LVL_INFO, .log_file = "app.log" };

    logger_write(&logger, LVL_DEBUG, "This debug trace will be filtered out");
    logger_write(&logger, LVL_INFO, "Worker thread started with ID %d", 4);
    logger_write(&logger, LVL_WARN, "Disk capacity at %d percent", 85);
    logger_write(&logger, LVL_ERROR, "Socket connection dropped unexpectedly");

    remove("app.log");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Matrix {
    int rows;
    int cols;
    double** data;
} Matrix;

Matrix* matrix_create(int rows, int cols) {
    Matrix* m = (Matrix*)malloc(sizeof(Matrix));
    if (!m) return NULL;
    m->rows = rows;
    m->cols = cols;
    m->data = (double**)malloc(rows * sizeof(double*));
    for (int i = 0; i < rows; i++) {
        m->data[i] = (double*)calloc(cols, sizeof(double));
    }
    return m;
}

void matrix_free(Matrix* m) {
    if (!m) return;
    for (int i = 0; i < m->rows; i++) {
        free(m->data[i]);
    }
    free(m->data);
    free(m);
}

Matrix* matrix_multiply(const Matrix* a, const Matrix* b) {
    if (a->cols != b->rows) return NULL;
    Matrix* res = matrix_create(a->rows, b->cols);
    for (int i = 0; i < a->rows; i++) {
        for (int j = 0; j < b->cols; j++) {
            double sum = 0.0;
            for (int k = 0; k < a->cols; k++) {
                sum += a->data[i][k] * b->data[k][j];
            }
            res->data[i][j] = sum;
        }
    }
    return res;
}

void matrix_print(const Matrix* m, const char* label) {
    printf("Matrix %s (%dx%d):
", label, m->rows, m->cols);
    for (int i = 0; i < m->rows; i++) {
        printf("  [ ");
        for (int j = 0; j < m->cols; j++) {
            printf("%6.1f ", m->data[i][j]);
        }
        printf("]
");
    }
}

int main(void) {
    Matrix* a = matrix_create(2, 2);
    a->data[0][0] = 1.0; a->data[0][1] = 2.0;
    a->data[1][0] = 3.0; a->data[1][1] = 4.0;

    Matrix* b = matrix_create(2, 2);
    b->data[0][0] = 2.0; b->data[0][1] = 0.0;
    b->data[1][0] = 1.0; b->data[1][1] = 2.0;

    Matrix* c = matrix_multiply(a, b);

    matrix_print(a, "A");
    matrix_print(b, "B");
    matrix_print(c, "C = A * B");

    matrix_free(a);
    matrix_free(b);
    matrix_free(c);
    return 0;
}

int string_length(const char* s) {
    int len = 0;
    while (s[len] != '\0') {
        len++;
    }
    return len;
}

void string_copy(char* dest, const char* src) {
    int i = 0;
    while (src[i] != '\0') {
        dest[i] = src[i];
        i++;
    }
    dest[i] = '\0';
}

void string_concat(char* dest, const char* src) {
    int i = 0;
    while (dest[i] != '\0') i++;
    int j = 0;
    while (src[j] != '\0') {
        dest[i++] = src[j++];
    }
    dest[i] = '\0';
}

int string_compare(const char* s1, const char* s2) {
    int i = 0;
    while (s1[i] != '\0' && s2[i] != '\0') {
        if (s1[i] != s2[i]) {
            return (unsigned char)s1[i] - (unsigned char)s2[i];
        }
        i++;
    }
    return (unsigned char)s1[i] - (unsigned char)s2[i];
}

void string_reverse(char* s) {
    int i = 0;
    while (s[i] != '\0') i++;
    int left = 0, right = i - 1;
    while (left < right) {
        char tmp = s[left];
        s[left] = s[right];
        s[right] = tmp;
        left++;
        right--;
    }
}

void string_to_lower(char* s) {
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] >= 'A' && s[i] <= 'Z') {
            s[i] = (char)(s[i] + 32);
        }
    }
}

void string_to_upper(char* s) {
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] >= 'a' && s[i] <= 'z') {
            s[i] = (char)(s[i] - 32);
        }
    }
}

int string_substring(const char* src, int start, int len, char* dest) {
    int src_len = 0;
    while (src[src_len] != '\0') src_len++;
    if (start < 0 || start >= src_len || len < 0) {
        dest[0] = '\0';
        return 0;
    }
    int i = 0;
    while (i < len && src[start + i] != '\0') {
        dest[i] = src[start + i];
        i++;
    }
    dest[i] = '\0';
    return i;
}

int string_find(const char* haystack, const char* needle) {
    if (needle[0] == '\0') return 0;
    for (int i = 0; haystack[i] != '\0'; i++) {
        int j = 0;
        while (haystack[i + j] != '\0' && needle[j] != '\0' && haystack[i + j] == needle[j]) {
            j++;
        }
        if (needle[j] == '\0') return i;
    }
    return -1;
}

void string_trim(char* s) {
    int start = 0;
    while (s[start] == ' ' || s[start] == '\t' || s[start] == '\n' || s[start] == '\r') {
        start++;
    }
    int end = start;
    while (s[end] != '\0') end++;
    end--;
    while (end >= start && (s[end] == ' ' || s[end] == '\t' || s[end] == '\n' || s[end] == '\r')) {
        end--;
    }
    int i = 0;
    for (int j = start; j <= end; j++) {
        s[i++] = s[j];
    }
    s[i] = '\0';
}

int string_word_count(const char* s) {
    int count = 0;
    int in_word = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] == ' ' || s[i] == '\t' || s[i] == '\n') {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            count++;
        }
    }
    return count;
}

void string_from_int(int val, char* dest) {
    if (val == 0) {
        dest[0] = '0';
        dest[1] = '\0';
        return;
    }
    int is_neg = 0;
    if (val < 0) {
        is_neg = 1;
        val = -val;
    }
    char buf[16];
    int idx = 0;
    while (val > 0) {
        buf[idx++] = (char)('0' + (val % 10));
        val /= 10;
    }
    int o = 0;
    if (is_neg) dest[o++] = '-';
    while (idx > 0) {
        dest[o++] = buf[--idx];
    }
    dest[o] = '\0';
}

int string_to_int(const char* s, int* out_val) {
    int i = 0;
    while (s[i] == ' ' || s[i] == '\t') i++;
    int sign = 1;
    if (s[i] == '-') {
        sign = -1;
        i++;
    } else if (s[i] == '+') {
        i++;
    }
    if (s[i] < '0' || s[i] > '9') return 0;
    int res = 0;
    while (s[i] >= '0' && s[i] <= '9') {
        res = res * 10 + (s[i] - '0');
        i++;
    }
    *out_val = res * sign;
    return 1;
}

#include <stdio.h>

int str_len(const char* s) {
    int len = 0;
    while (s[len] != '\0') len++;
    return len;
}

void str_cpy(char* d, const char* s) {
    int i = 0;
    while (s[i] != '\0') { d[i] = s[i]; i++; }
    d[i] = '\0';
}

void str_cat(char* d, const char* s) {
    int i = 0;
    while (d[i] != '\0') i++;
    int j = 0;
    while (s[j] != '\0') d[i++] = s[j++];
    d[i] = '\0';
}

int str_cmp(const char* a, const char* b) {
    int i = 0;
    while (a[i] != '\0' && b[i] != '\0') {
        if (a[i] != b[i]) return (unsigned char)a[i] - (unsigned char)b[i];
        i++;
    }
    return (unsigned char)a[i] - (unsigned char)b[i];
}

void str_rev(char* s) {
    int l = 0, r = str_len(s) - 1;
    while (l < r) {
        char t = s[l]; s[l] = s[r]; s[r] = t;
        l++; r--;
    }
}

int main(void) {
    char buf[64];
    str_cpy(buf, "Hello");
    str_cat(buf, ", World!");
    printf("String: '%s' (Length: %d)\n", buf, str_len(buf));
    printf("Comparison with 'Hello': %d\n", str_cmp(buf, "Hello"));
    str_rev(buf);
    printf("Reversed: '%s'\n", buf);
    return 0;
}

