}

#include <stdio.h>

void str_trim(char* s) {
    int start = 0;
    while (s[start] == ' ' || s[start] == '\t') start++;
    int end = start;
    while (s[end] != '\0') end++;
    end--;
    while (end >= start && (s[end] == ' ' || s[end] == '\t')) end--;
    int i = 0;
    for (int j = start; j <= end; j++) s[i++] = s[j];
    s[i] = '\0';
}

void str_upper(char* s) {
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] >= 'a' && s[i] <= 'z') s[i] = (char)(s[i] - 32);
    }
}

int str_to_int(const char* s) {
    int i = 0, res = 0, sign = 1;
    while (s[i] == ' ') i++;
    if (s[i] == '-') { sign = -1; i++; }
    else if (s[i] == '+') i++;
    while (s[i] >= '0' && s[i] <= '9') {
        res = res * 10 + (s[i] - '0');
        i++;
    }
    return res * sign;
}

int main(void) {
    char s[] = "   hello dtyp user   ";
    str_trim(s);
    printf("Trimmed: '%s'\n", s);
    str_upper(s);
    printf("Uppercase: '%s'\n", s);
    const char* num_str = " -12345 ";
    printf("Converted integer: %d\n", str_to_int(num_str));
    return 0;
}

void array_1d_reverse(int* arr, int n) {
    int start = 0, end = n - 1;
    while (start < end) {
        int tmp = arr[start];
        arr[start] = arr[end];
        arr[end] = tmp;
        start++;
        end--;
    }
}

void array_1d_rotate(int* arr, int n, int k) {
    if (n <= 0) return;
    k = k % n;
    if (k < 0) k += n;
    for (int i = 0; i < k; i++) {
        int first = arr[0];
        for (int j = 0; j < n - 1; j++) {
            arr[j] = arr[j + 1];
        }
        arr[n - 1] = first;
    }
}

int array_1d_binary_search(const int* arr, int n, int target) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

void array_1d_min_max(const int* arr, int n, int* min_val, int* max_val) {
    if (n <= 0) return;
    *min_val = arr[0];
    *max_val = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] < *min_val) *min_val = arr[i];
        if (arr[i] > *max_val) *max_val = arr[i];
    }
}

