Node* createNode(int data) {
    Node* n = (Node*)malloc(sizeof(Node));
    if (!n) return NULL;
    n->data = data;
    n->next = NULL;
    return n;
}

void singly_insert_head(Node** head, int data) {
    Node* n = createNode(data);
    if (!n) return;
    n->next = *head;
    *head = n;
}

void singly_insert_tail(Node** head, int data) {
    Node* n = createNode(data);
    if (!n) return;
    if (*head == NULL) {
        *head = n;
        return;
    }
    Node* cur = *head;
    while (cur->next != NULL) {
        cur = cur->next;
    }
    cur->next = n;
}

void singly_insert_after(Node* target, int data) {
    if (!target) return;
    Node* n = createNode(data);
    if (!n) return;
    n->next = target->next;
    target->next = n;
}

void singly_insert_before(Node** head, int target_val, int data) {
    if (!head || !*head) return;
    if ((*head)->data == target_val) {
        singly_insert_head(head, data);
        return;
    }
    Node* cur = *head;
    while (cur->next && cur->next->data != target_val) {
        cur = cur->next;
    }
    if (cur->next) {
        Node* n = createNode(data);
        if (!n) return;
        n->next = cur->next;
        cur->next = n;
    }
}

int singly_delete_value(Node** head, int val) {
    if (!head || !*head) return 0;
    Node* cur = *head;
    if (cur->data == val) {
        *head = cur->next;
        free(cur);
        return 1;
    }
    while (cur->next && cur->next->data != val) {
        cur = cur->next;
    }
    if (cur->next) {
        Node* del = cur->next;
        cur->next = del->next;
        free(del);
        return 1;
    }
    return 0;
}

Node* singly_search(Node* head, int val) {
    Node* cur = head;
    while (cur != NULL) {
        if (cur->data == val) return cur;
        cur = cur->next;
    }
    return NULL;
}

int singly_count(const Node* head) {
    int cnt = 0;
    const Node* cur = head;
    while (cur != NULL) {
        cnt++;
        cur = cur->next;
