    n->dest = v;
    n->next = g->adj[u];
    g->adj[u] = n;
}

typedef struct GraphDSU {
    int* parent;
    int* rank;
    int n;
} GraphDSU;

int graph_dsu_find(GraphDSU* dsu, int i) {
    if (dsu->parent[i] == i) return i;
    return dsu->parent[i] = graph_dsu_find(dsu, dsu->parent[i]);
}

void graph_dsu_union(GraphDSU* dsu, int x, int y) {
    int root_x = graph_dsu_find(dsu, x);
    int root_y = graph_dsu_find(dsu, y);
    if (root_x != root_y) {
        if (dsu->rank[root_x] < dsu->rank[root_y]) {
            dsu->parent[root_x] = root_y;
        } else if (dsu->rank[root_x] > dsu->rank[root_y]) {
            dsu->parent[root_y] = root_x;
        } else {
            dsu->parent[root_y] = root_x;
            dsu->rank[root_x]++;
        }
    }
}

typedef struct Node {
    char key[32];
    int value;
    struct Node* next;
} Node;
typedef Node HashNode;

typedef struct ChainHashTable {
    Node** buckets;
    int size;
} ChainHashTable;

static unsigned long hash_str(const char* s, int mod) {
    unsigned long h = 5381;
    int c;
    while ((c = *s++)) h = ((h << 5) + h) + c;
    return h % mod;
}

void chain_hash_insert(ChainHashTable* ht, const char* key, int value) {
    unsigned long b = hash_str(key, ht->size);
    Node* cur = ht->buckets[b];
    while (cur) {
        if (strcmp(cur->key, key) == 0) {
            cur->value = value;
            return;
        }
        cur = cur->next;
    }
    Node* n = (Node*)malloc(sizeof(Node));
    if (!n) return;
    strncpy(n->key, key, sizeof(n->key) - 1);
    n->key[sizeof(n->key) - 1] = '�';
    n->value = value;
    n->next = ht->buckets[b];
    ht->buckets[b] = n;
}

typedef struct OpenEntry {
    char key[32];
    int value;
    bool occupied;
} OpenEntry;

typedef struct OpenHashTable {
    OpenEntry* entries;
    int capacity;
    int count;
} OpenHashTable;

static unsigned long open_hash_calc(const char* s, int mod) {
    unsigned long h = 5381;
    int c;
    while ((c = *s++)) h = ((h << 5) + h) + c;
    return h % mod;
}

int open_hash_insert(OpenHashTable* ht, const char* key, int value) {
    if (ht->count >= ht->capacity / 2) return 0;
    unsigned long idx = open_hash_calc(key, ht->capacity);
    while (ht->entries[idx].occupied) {
        if (strcmp(ht->entries[idx].key, key) == 0) {
            ht->entries[idx].value = value;
            return 1;
        }
        idx = (idx + 1) % ht->capacity;
    }
    strncpy(ht->entries[idx].key, key, sizeof(ht->entries[idx].key) - 1);
    ht->entries[idx].key[sizeof(ht->entries[idx].key) - 1] = '�';
    ht->entries[idx].value = value;
    ht->entries[idx].occupied = true;
    ht->count++;
    return 1;
}

unsigned long hash_djb2(const char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c;
    }
    return hash;
}

uint32_t hash_fnv1a(const char* str) {
    uint32_t hash = 2166136261u;
    while (*str) {
        hash ^= (uint8_t)(*str++);
        hash *= 16777619u;
    }
    return hash;
}

#include <stdio.h>

void reverse_arr(int* arr, int n) {
    int s = 0, e = n - 1;
    while (s < e) {
        int t = arr[s]; arr[s] = arr[e]; arr[e] = t;
        s++; e--;
    }
}

int bin_search(const int* arr, int n, int target) {
    int l = 0, r = n - 1;
    while (l <= r) {
        int m = l + (r - l) / 2;
        if (arr[m] == target) return m;
        if (arr[m] < target) l = m + 1;
        else r = m - 1;
    }
    return -1;
}

int main(void) {
