    putchar('
');

    int idx = bin_search(arr, n, 48);
    printf("Binary search for 48: index %d
", idx);

    reverse_arr(arr, n);
    printf("Reversed Array: ");
    for (int i = 0; i < n; i++) printf("%d ", arr[i]);
    putchar('
');

    return 0;
}

