} Stack;

Stack* stack_create(int cap) {
    Stack* s = (Stack*)malloc(sizeof(Stack));
    s->data = (int*)malloc(cap * sizeof(int));
    s->top = -1;
    s->cap = cap;
    return s;
}

void stack_push(Stack* s, int val) {
    if (s->top >= s->cap - 1) {
        s->cap *= 2;
        s->data = (int*)realloc(s->data, s->cap * sizeof(int));
    }
    s->data[++s->top] = val;
}

int stack_pop(Stack* s) {
    if (s->top < 0) return -1;
    return s->data[s->top--];
}

