    int front;
    int rear;
    int count;
} CircularQueue;

int cq_push(CircularQueue* q, int val) {
    if (q->count == CAP) return 0;
    q->rear = (q->rear + 1) % CAP;
    q->data[q->rear] = val;
    q->count++;
    return 1;
}

int cq_pop(CircularQueue* q, int* val) {
    if (q->count == 0) return 0;
    *val = q->data[q->front];
    q->front = (q->front + 1) % CAP;
    q->count--;
    return 1;
}

