int dsu_find(int i) {
    if (parent[i] == i) return i;
    return parent[i] = dsu_find(parent[i]);
}

void dsu_union(int x, int y) {
    int rx = dsu_find(x);
    int ry = dsu_find(y);
    if (rx != ry) {
        if (rank_val[rx] < rank_val[ry]) parent[rx] = ry;
        else if (rank_val[rx] > rank_val[ry]) parent[ry] = rx;
        else { parent[ry] = rx; rank_val[rx]++; }
    }
}

