int cp_two_pointers_pair_sum(const int* arr, int n, int target, int* out_i, int* out_j) {
    int left = 0, right = n - 1;
    while (left < right) {
        int sum = arr[left] + arr[right];
        if (sum == target) {
            *out_i = left;
            *out_j = right;
            return 1;
        }
        if (sum < target) left++;
        else right--;
    }
    return 0;
}

int cp_two_pointers_remove_duplicates(int* arr, int n) {
    if (n <= 1) return n;
    int slow = 0;
    for (int fast = 1; fast < n; fast++) {
        if (arr[fast] != arr[slow]) {
            slow++;
            arr[slow] = arr[fast];
        }
    }
    return slow + 1;
}

long long cp_two_pointers_trapping_rain_water(const int* heights, int n) {
    if (n <= 2) return 0;
    int left = 0, right = n - 1;
    int left_max = 0, right_max = 0;
    long long total_water = 0;
    while (left <= right) {
        if (heights[left] <= heights[right]) {
            if (heights[left] >= left_max) left_max = heights[left];
            else total_water += (left_max - heights[left]);
            left++;
        } else {
            if (heights[right] >= right_max) right_max = heights[right];
            else total_water += (right_max - heights[right]);
            right--;
        }
    }
    return total_water;
}

long long cp_sliding_window_fixed_sum(const int* arr, int n, int k) {
    if (n < k || k <= 0) return 0;
    long long current_sum = 0;
    for (int i = 0; i < k; i++) current_sum += arr[i];
    long long max_sum = current_sum;
    for (int i = k; i < n; i++) {
        current_sum += arr[i] - arr[i - k];
        if (current_sum > max_sum) max_sum = current_sum;
    }
    return max_sum;
}

int cp_sliding_window_min_subarray_len(const int* arr, int n, long long target) {
    int min_len = n + 1;
    long long current_sum = 0;
    int left = 0;
    for (int right = 0; right < n; right++) {
        current_sum += arr[right];
        while (current_sum >= target) {
            int len = right - left + 1;
            if (len < min_len) min_len = len;
            current_sum -= arr[left++];
        }
    }
    return (min_len <= n) ? min_len : 0;
}

typedef struct CpFenwickTree {
    long long* tree;
    int size;
} CpFenwickTree;

void cp_fenwick_update(CpFenwickTree* ft, int idx, long long delta) {
    while (idx <= ft->size) {
        ft->tree[idx] += delta;
        idx += (idx & (-idx));
    }
}

long long cp_fenwick_query(const CpFenwickTree* ft, int idx) {
    long long sum = 0;
    while (idx > 0) {
        sum += ft->tree[idx];
        idx -= (idx & (-idx));
    }
    return sum;
}

typedef struct CpSegmentTree {
    long long* tree;
    int n;
} CpSegmentTree;

void cp_seg_tree_build(CpSegmentTree* st, const int* arr, int node, int start, int end) {
    if (start == end) {
        st->tree[node] = arr[start];
        return;
    }
    int mid = start + (end - start) / 2;
    cp_seg_tree_build(st, arr, 2 * node, start, mid);
    cp_seg_tree_build(st, arr, 2 * node + 1, mid + 1, end);
    st->tree[node] = (st->tree[2 * node] < st->tree[2 * node + 1]) ? st->tree[2 * node] : st->tree[2 * node + 1];
}

void cp_seg_tree_update(CpSegmentTree* st, int node, int start, int end, int idx, long long val) {
    if (start == end) {
        st->tree[node] = val;
        return;
    }
    int mid = start + (end - start) / 2;
    if (idx <= mid) cp_seg_tree_update(st, 2 * node, start, mid, idx, val);
    else cp_seg_tree_update(st, 2 * node + 1, mid + 1, end, idx, val);
    st->tree[node] = (st->tree[2 * node] < st->tree[2 * node + 1]) ? st->tree[2 * node] : st->tree[2 * node + 1];
}

long long cp_seg_tree_query(const CpSegmentTree* st, int node, int start, int end, int l, int r) {
    if (r < start || end < l) return 9223372036854775807LL;
    if (l <= start && end <= r) return st->tree[node];
    int mid = start + (end - start) / 2;
    long long left_min = cp_seg_tree_query(st, 2 * node, start, mid, l, r);
    long long right_min = cp_seg_tree_query(st, 2 * node + 1, mid + 1, end, l, r);
    return (left_min < right_min) ? left_min : right_min;
}

typedef struct CpDsu {
    int* parent;
    int* rank;
    int size;
} CpDsu;

void cp_dsu_init(CpDsu* dsu, int n, int* parent_buf, int* rank_buf) {
    dsu->parent = parent_buf;
    dsu->rank = rank_buf;
    dsu->size = n;
    for (int i = 0; i < n; i++) {
        dsu->parent[i] = i;
        dsu->rank[i] = 0;
    }
}

int cp_dsu_find(CpDsu* dsu, int i) {
    if (dsu->parent[i] == i) return i;
    dsu->parent[i] = cp_dsu_find(dsu, dsu->parent[i]);
    return dsu->parent[i];
}

int cp_dsu_union(CpDsu* dsu, int i, int j) {
    int root_i = cp_dsu_find(dsu, i);
    int root_j = cp_dsu_find(dsu, j);
    if (root_i == root_j) return 0;
    if (dsu->rank[root_i] < dsu->rank[root_j]) {
        dsu->parent[root_i] = root_j;
    } else if (dsu->rank[root_i] > dsu->rank[root_j]) {
        dsu->parent[root_j] = root_i;
    } else {
        dsu->parent[root_j] = root_i;
        dsu->rank[root_i]++;
    }
    return 1;
}

void cp_monotonic_stack_next_greater(const int* arr, int n, int* next_idx) {
    int stack[n];
    int top = -1;
    for (int i = 0; i < n; i++) next_idx[i] = -1;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && arr[i] > arr[stack[top]]) {
            next_idx[stack[top--]] = i;
        }
        stack[++top] = i;
    }
}

void cp_monotonic_sliding_window_max(const int* arr, int n, int k, int* out_max) {
    int deque[n];
    int head = 0, tail = 0;
    int out_idx = 0;
    for (int i = 0; i < n; i++) {
        if (head < tail && deque[head] <= i - k) head++;
        while (head < tail && arr[deque[tail - 1]] <= arr[i]) tail--;
        deque[tail++] = i;
        if (i >= k - 1) {
            out_max[out_idx++] = arr[deque[head]];
        }
    }
}

long long cp_binary_search_answer_min(long long low, long long high, int (*predicate)(long long, void*), void* context) {
    long long ans = high;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (predicate(mid, context)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}

long long cp_binary_search_answer_max(long long low, long long high, int (*predicate)(long long, void*), void* context) {
    long long ans = low;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (predicate(mid, context)) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
}

long long cp_ternary_search_unimodal_max(long long low, long long high, long long (*f)(long long)) {
    while (high - low >= 3) {
        long long m1 = low + (high - low) / 3;
        long long m2 = high - (high - low) / 3;
        if (f(m1) < f(m2)) low = m1;
        else high = m2;
    }
    long long best_x = low;
    long long best_val = f(low);
    for (long long x = low + 1; x <= high; x++) {
        long long val = f(x);
        if (val > best_val) {
            best_val = val;
            best_x = x;
        }
    }
    return best_x;
}

void cp_zero_one_bfs(int n, const int* head, const int* to, const int* weight, const int* next, int src, int* dist) {
    for (int i = 0; i < n; i++) dist[i] = 1000000000;
    int deque[2 * n + 5];
    int front = n + 2, back = n + 2;
    dist[src] = 0;
    deque[back++] = src;
    while (front < back) {
        int u = deque[front++];
        for (int e = head[u]; e != -1; e = next[e]) {
            int v = to[e];
            int w = weight[e];
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                if (w == 0) deque[--front] = v;
                else deque[back++] = v;
            }
        }
    }
}

void cp_lca_binary_lifting_build(int n, int max_log, const int* parent, int* up) {
    for (int i = 0; i < n; i++) {
        up[i * max_log + 0] = parent[i];
    }
    for (int j = 1; j < max_log; j++) {
        for (int i = 0; i < n; i++) {
            int p = up[i * max_log + (j - 1)];
            if (p != -1) up[i * max_log + j] = up[p * max_log + (j - 1)];
            else up[i * max_log + j] = -1;
        }
    }
}

int cp_lca_query(int u, int v, int max_log, const int* depth, const int* up) {
    if (depth[u] < depth[v]) {
        int tmp = u; u = v; v = tmp;
    }
    for (int j = max_log - 1; j >= 0; j--) {
        if (depth[u] - (1 << j) >= depth[v]) {
            u = up[u * max_log + j];
        }
    }
    if (u == v) return u;
    for (int j = max_log - 1; j >= 0; j--) {
        if (up[u * max_log + j] != up[v * max_log + j]) {
            u = up[u * max_log + j];
            v = up[v * max_log + j];
        }
    }
    return up[u * max_log + 0];
}

void cp_tarjan_scc(int u, const int* head, const int* to, const int* next, int* disc, int* low, int* in_stack, int* stack, int* top, int* timer, int* scc_id, int* scc_count) {
    disc[u] = low[u] = ++(*timer);
    stack[++(*top)] = u;
    in_stack[u] = 1;
    for (int e = head[u]; e != -1; e = next[e]) {
        int v = to[e];
        if (disc[v] == 0) {
            cp_tarjan_scc(v, head, to, next, disc, low, in_stack, stack, top, timer, scc_id, scc_count);
            if (low[v] < low[u]) low[u] = low[v];
        } else if (in_stack[v]) {
            if (disc[v] < low[u]) low[u] = disc[v];
        }
    }
    if (low[u] == disc[u]) {
        (*scc_count)++;
        while (1) {
            int node = stack[(*top)--];
            in_stack[node] = 0;
            scc_id[node] = *scc_count;
            if (node == u) break;
        }
    }
}

