    precompute_fact(100, mod, fact, inv_fact);
    printf("10C3 mod 1e9+7 = %lld
", ncr(10, 3, mod, fact, inv_fact));
    printf("50C5 mod 1e9+7 = %lld
", ncr(50, 5, mod, fact, inv_fact));
