    long long tree[9] = {0};
    int initial[] = {0, 1, 3, 5, 7, 9, 11, 13, 15};
    for (int i = 1; i <= n; i++) {
        fenwick_update(tree, n, i, initial[i]);
    }
    printf("Prefix sum(5): %lld
", fenwick_query(tree, 5));
    printf("Range sum(3..6): %lld
", fenwick_query(tree, 6) - fenwick_query(tree, 2));
    fenwick_update(tree, n, 4, 10);
    printf("Range sum(3..6) after +10 at idx 4: %lld
", fenwick_query(tree, 6) - fenwick_query(tree, 2));
    return 0;
}

#include <stdio.h>

void seg_build(long long* tree, const int* arr, int node, int start, int end) {
    if (start == end) {
        tree[node] = arr[start];
        return;
    }
    int mid = start + (end - start) / 2;
    seg_build(tree, arr, 2 * node, start, mid);
    seg_build(tree, arr, 2 * node + 1, mid + 1, end);
    tree[node] = (tree[2 * node] < tree[2 * node + 1]) ? tree[2 * node] : tree[2 * node + 1];
}

void seg_update(long long* tree, int node, int start, int end, int idx, long long val) {
    if (start == end) {
        tree[node] = val;
        return;
    }
    int mid = start + (end - start) / 2;
    if (idx <= mid) seg_update(tree, 2 * node, start, mid, idx, val);
    else seg_update(tree, 2 * node + 1, mid + 1, end, idx, val);
    tree[node] = (tree[2 * node] < tree[2 * node + 1]) ? tree[2 * node] : tree[2 * node + 1];
}

long long seg_query(const long long* tree, int node, int start, int end, int l, int r) {
    if (r < start || end < l) return 9223372036854775807LL;
    if (l <= start && end <= r) return tree[node];
    int mid = start + (end - start) / 2;
    long long l_min = seg_query(tree, 2 * node, start, mid, l, r);
    long long r_min = seg_query(tree, 2 * node + 1, mid + 1, end, l, r);
    return (l_min < r_min) ? l_min : r_min;
}

int main(void) {
    int arr[] = {18, 17, 13, 19, 15, 11, 20};
    int n = 7;
    long long tree[30];
    seg_build(tree, arr, 1, 0, n - 1);
    printf("Min in range [1, 4]: %lld
", seg_query(tree, 1, 0, n - 1, 1, 4));
    seg_update(tree, 1, 0, n - 1, 2, 5);
    printf("Min in range [1, 4] after update idx 2 to 5: %lld
", seg_query(tree, 1, 0, n - 1, 1, 4));
    return 0;
}

#include <stdio.h>

int dsu_find(int* parent, int i) {
    if (parent[i] == i) return i;
    parent[i] = dsu_find(parent, parent[i]);
    return parent[i];
}

int dsu_union(int* parent, int* rank, int i, int j) {
    int root_i = dsu_find(parent, i);
    int root_j = dsu_find(parent, j);
    if (root_i == root_j) return 0;
    if (rank[root_i] < rank[root_j]) {
        parent[root_i] = root_j;
    } else if (rank[root_i] > rank[root_j]) {
        parent[root_j] = root_i;
    } else {
        parent[root_j] = root_i;
        rank[root_i]++;
    }
    return 1;
}

int main(void) {
    int n = 5;
    int parent[5], rank[5];
    for (int i = 0; i < n; i++) { parent[i] = i; rank[i] = 0; }
    dsu_union(parent, rank, 0, 1);
    dsu_union(parent, rank, 2, 3);
    dsu_union(parent, rank, 1, 2);
    printf("Are 0 and 3 connected: %s
", dsu_find(parent, 0) == dsu_find(parent, 3) ? "Yes" : "No");
    printf("Are 0 and 4 connected: %s
", dsu_find(parent, 0) == dsu_find(parent, 4) ? "Yes" : "No");
    return 0;
}

