double solve_false_position(double a, double b, double tol, int max_iter) {
    if (f(a) * f(b) >= 0) return a;
    double c = a;
    for (int i = 0; i < max_iter; i++) {
        c = (a * f(b) - b * f(a)) / (f(b) - f(a));
        if (fabs(f(c)) < tol) break;
        if (f(c) * f(a) < 0) b = c;
        else a = c;
    }
    return c;
}

