        {1.0, 1.0, 2.0, 4.0},
        {2.0, 1.0, 1.0, 4.0}
    };
    double x[3];
    solve_gauss_pivoting(n, a, x);
    for (int i = 0; i < n; i++) {
        printf("x[%d] = %.4f
", i, x[i]);
    }
    return 0;
}

