    int n = 3;
    double a[3][4] = {
        {2, 1, 1, 10},
        {3, 2, 3, 18},
        {1, 4, 9, 16}
    };
    double x[3];
    solve_gauss_jordan(n, a, x);
    for (int i = 0; i < n; i++) {
        printf("x[%d] = %.4f
", i, x[i]);
    }
    return 0;
}

#include <stdio.h>

void solve_lud(int n, const double A[n][n], const double b[n], double x[n]) {
    double L[n][n], U[n][n], y[n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            L[i][j] = (i == j) ? 1.0 : 0.0;
            U[i][j] = 0.0;
        }
    }
    for (int i = 0; i < n; i++) {
        for (int k = i; k < n; k++) {
            double sum = 0;
            for (int j = 0; j < i; j++) sum += (L[i][j] * U[j][k]);
            U[i][k] = A[i][k] - sum;
        }
        for (int k = i + 1; k < n; k++) {
            double sum = 0;
            for (int j = 0; j < i; j++) sum += (L[k][j] * U[j][i]);
            L[k][i] = (A[k][i] - sum) / U[i][i];
        }
    }
    for (int i = 0; i < n; i++) {
        double sum = b[i];
        for (int j = 0; j < i; j++) sum -= L[i][j] * y[j];
        y[i] = sum;
    }
    for (int i = n - 1; i >= 0; i--) {
        double sum = y[i];
        for (int j = i + 1; j < n; j++) sum -= U[i][j] * x[j];
        x[i] = sum / U[i][i];
    }
}

int main(void) {
