    double A[3][3] = {
        {2, -1, -2},
        {-4, 6, 3},
        {-4, -2, 8}
    };
    double b[3] = {-1, 13, -6};
    double x[3];
    solve_lud(n, A, b, x);
    for (int i = 0; i < n; i++) {
        printf("x[%d] = %.4f
", i, x[i]);
    }
    return 0;
}

