double interpolate_lagrange(int n, const double x_pts[], const double y_pts[], double x_target) {
    double result = 0.0;
    for (int i = 0; i < n; i++) {
        double term = y_pts[i];
        for (int j = 0; j < n; j++) {
            if (j != i) {
                term *= (x_target - x_pts[j]) / (x_pts[i] - x_pts[j]);
            }
        }
        result += term;
    }
    return result;
}

