#include <stdio.h>

double interpolate_newton_forward(int n, const double x[], const double y[], double target) {
    double diff[n][n];
    for (int i = 0; i < n; i++) diff[i][0] = y[i];
    for (int j = 1; j < n; j++) {
        for (int i = 0; i < n - j; i++) {
            diff[i][j] = diff[i + 1][j - 1] - diff[i][j - 1];
        }
    }
    double h = x[1] - x[0];
    double u = (target - x[0]) / h;
    double sum = diff[0][0];
    double u_term = 1.0;
    double fact = 1.0;
    for (int j = 1; j < n; j++) {
        u_term *= (u - (j - 1));
        fact *= j;
        sum += (u_term * diff[0][j]) / fact;
    }
    return sum;
}

