double df(double x, double h) {
    return (f(x + h) - f(x - h)) / (2.0 * h);
}

double d2f(double x, double h) {
    return (f(x + h) - 2.0 * f(x) + f(x - h)) / (h * h);
}

void find_extrema(double a, double b, int n) {
    double dx = (b - a) / n;
    double h = 1e-4;
    for (int i = 0; i < n; i++) {
        double x1 = a + i * dx;
        double x2 = x1 + dx;
        if (df(x1, h) * df(x2, h) <= 0) {
            double root = (x1 + x2) / 2.0;
            double concavity = d2f(root, h);
            if (concavity < 0) {
                printf("Local Maximum at x = %.4f, f(x) = %.4f
", root, f(root));
            } else if (concavity > 0) {
                printf("Local Minimum at x = %.4f, f(x) = %.4f
", root, f(root));
            }
        }
    }
}

