    double A[3][3] = {
        {1, 2, 3},
        {0, 1, 4},
        {5, 6, 0}
    };
    double inv[3][3];
    double det;
    if (invert_matrix(n, A, inv, &det)) {
        printf("Determinant: %.4f
", det);
        printf("Inverse Matrix:
");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) printf("%8.4f ", inv[i][j]);
            printf("
");
        }
    }
    return 0;
}

