void analyze_beam(double L, int n_loads, const double P[], const double a[]) {
    double moment_A = 0.0, total_load = 0.0;
    for (int i = 0; i < n_loads; i++) {
        moment_A += P[i] * a[i];
        total_load += P[i];
    }
    double R_B = moment_A / L;
    double R_A = total_load - R_B;

    printf("Reaction at A: %.2f N
", R_A);
    printf("Reaction at B: %.2f N
", R_B);

    double max_moment = 0.0;
    for (int i = 0; i < n_loads; i++) {
        double m = R_A * a[i];
        for (int j = 0; j < i; j++) {
            m -= P[j] * (a[i] - a[j]);
        }
        if (m > max_moment) max_moment = m;
    }
    printf("Max Bending Moment under point loads: %.2f N*m
", max_moment);
}

int main(void) {
    double L = 10.0;
    int n = 2;
    double P[] = {20.0, 30.0};
    double a[] = {3.0, 7.0};
