", v2);
    printf("Initial Kinetic Energy: %.2f J
", ke_initial);
    printf("Final Kinetic Energy:   %.2f J
", ke_final);
    printf("Kinetic Energy Loss:    %.2f J (%.1f%%)
", ke_loss, (ke_loss / ke_initial) * 100.0);
