void compute_descriptive_stats(int n, double arr[]) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                double tmp = arr[j]; arr[j] = arr[j + 1]; arr[j + 1] = tmp;
            }
        }
    }
    double sum = 0.0;
    for (int i = 0; i < n; i++) sum += arr[i];
    double mean = sum / n;

    double median = (n % 2 != 0) ? arr[n / 2] : (arr[n / 2 - 1] + arr[n / 2]) / 2.0;

    double sq_diff = 0.0;
    for (int i = 0; i < n; i++) sq_diff += (arr[i] - mean) * (arr[i] - mean);
    double variance = sq_diff / (n - 1);
    double std_dev = sqrt(variance);

    double q1 = arr[n / 4];
    double q3 = arr[(3 * n) / 4];
    double iqr = q3 - q1;

    printf("Mean:               %.4f
", mean);
    printf("Median:             %.4f
", median);
    printf("Sample Variance:    %.4f
", variance);
    printf("Standard Deviation: %.4f
", std_dev);
    printf("IQR (Q3 - Q1):      %.4f
", iqr);
}

int main(void) {
    double data[] = {12, 15, 11, 19, 22, 24, 25, 26, 29, 35};
    compute_descriptive_stats(10, data);
    return 0;
}

