long long ncr(int n, int r) {
    if (r < 0 || r > n) return 0;
    if (r > n - r) r = n - r;
    long long res = 1;
    for (int i = 1; i <= r; i++) res = res * (n - i + 1) / i;
    return res;
}

double binomial_pmf(int n, int k, double p) {
    return ncr(n, k) * pow(p, k) * pow(1.0 - p, n - k);
}

double poisson_pmf(double lambda, int k) {
    double fact = 1.0;
    for (int i = 1; i <= k; i++) fact *= i;
    return (exp(-lambda) * pow(lambda, k)) / fact;
}

int main(void) {
    printf("Binomial(n=10, p=0.3, k=3): %.6f
", binomial_pmf(10, 3, 0.3));
    printf("Poisson(lambda=2.5, k=2):   %.6f
", poisson_pmf(2.5, 2));
    return 0;
}

