double normal_pdf(double x, double mu, double sigma) {
    double coeff = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793));
    double exp_part = exp(-0.5 * pow((x - mu) / sigma, 2.0));
    return coeff * exp_part;
}

double normal_cdf(double x, double mu, double sigma) {
    double z = (x - mu) / (sigma * sqrt(2.0));
    return 0.5 * (1.0 + erf(z));
}

int main(void) {
    double mu = 100.0, sigma = 15.0, query = 115.0;
    double z = (query - mu) / sigma;
    printf("Z-Score: %.4f
", z);
    printf("PDF f(115): %.6f
", normal_pdf(query, mu, sigma));
    printf("CDF P(X <= 115): %.6f
", normal_cdf(query, mu, sigma));
    return 0;
}

#include <stdio.h>
#include <math.h>

void solve_linear_regression(int n, const double x[], const double y[], double query_x) {
    double sum_x = 0, sum_y = 0, sum_xy = 0, sum_x2 = 0, sum_y2 = 0;
    for (int i = 0; i < n; i++) {
        sum_x += x[i];
        sum_y += y[i];
        sum_xy += x[i] * y[i];
        sum_x2 += x[i] * x[i];
        sum_y2 += y[i] * y[i];
    }
    double m = (n * sum_xy - sum_x * sum_y) / (n * sum_x2 - sum_x * sum_x);
    double c = (sum_y - m * sum_x) / n;
    double num_r = (n * sum_xy - sum_x * sum_y);
    double den_r = sqrt((n * sum_x2 - sum_x * sum_x) * (n * sum_y2 - sum_y * sum_y));
    double r = num_r / den_r;
    double r2 = r * r;
    double pred_y = m * query_x + c;

    printf("Slope (m):                     %.4f
", m);
    printf("Intercept (c):                 %.4f
", c);
    printf("Regression Equation:           y = %.4fx + %.4f
", m, c);
    printf("Pearson Correlation (r):       %.4f
", r);
    printf("R-Squared (r^2):               %.4f
", r2);
    printf("Prediction at x = %.2f:       y = %.4f
", query_x, pred_y);
}

int main(void) {
    int n = 5;
    double x[] = {1, 2, 3, 4, 5};
    double y[] = {2, 3, 5, 6, 8};
    solve_linear_regression(n, x, y, 6.0);
    return 0;
}

