    for (int i = 0; i < n; i++) {
        database[i].gpa = calculate_gpa(database[i].marks);
    }
    printf("=== Student Database ===
");
    for (int i = 0; i < n; i++) print_student(&database[i]);
    rank_students(database, n);
    printf("
