        if (*ptr == '"') {
            ptr++;
            char key[32] = {0};
            int ki = 0;
            while (*ptr && *ptr != '"' && ki < 31) key[ki++] = *ptr++;
            if (*ptr == '"') ptr++;
            while (*ptr && (*ptr == ' ' || *ptr == ':')) ptr++;
            char val[64] = {0};
            int vi = 0;
            if (*ptr == '"') {
                ptr++;
                while (*ptr && *ptr != '"' && vi < 63) val[vi++] = *ptr++;
                if (*ptr == '"') ptr++;
            } else {
                while (*ptr && *ptr != ',' && *ptr != '}' && vi < 63) val[vi++] = *ptr++;
            }
            printf("  Key: '%s' => Value: '%s'
", key, val);
        } else {
            ptr++;
        }
    }
}

