#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

int precedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

int apply_op(int a, int b, char op) {
    if (op == '+') return a + b;
    if (op == '-') return a - b;
    if (op == '*') return a * b;
    if (op == '/' && b != 0) return a / b;
    return 0;
}

int evaluate_expr(const char* expr) {
    int vals[50]; int val_top = -1;
    char ops[50]; int op_top = -1;
    for (int i = 0; expr[i]; i++) {
        if (expr[i] == ' ') continue;
        if (isdigit(expr[i])) {
            int val = 0;
            while (isdigit(expr[i])) val = val * 10 + (expr[i++] - '0');
            i--;
            vals[++val_top] = val;
        } else if (expr[i] == '(') {
            ops[++op_top] = '(';
        } else if (expr[i] == ')') {
            while (op_top >= 0 && ops[op_top] != '(') {
                int v2 = vals[val_top--]; int v1 = vals[val_top--];
                vals[++val_top] = apply_op(v1, v2, ops[op_top--]);
            }
            if (op_top >= 0) op_top--;
        } else {
            while (op_top >= 0 && precedence(ops[op_top]) >= precedence(expr[i])) {
                int v2 = vals[val_top--]; int v1 = vals[val_top--];
                vals[++val_top] = apply_op(v1, v2, ops[op_top--]);
            }
            ops[++op_top] = expr[i];
        }
    }
    while (op_top >= 0) {
        int v2 = vals[val_top--]; int v1 = vals[val_top--];
        vals[++val_top] = apply_op(v1, v2, ops[op_top--]);
    }
    return vals[val_top];
}

int main(void) {
    const char* expr = "3 + 5 * (2 - 8)";
    printf("%s = %d
", expr, evaluate_expr(expr));
    return 0;
}

