#include <stdio.h>

int match_here(const char* regexp, const char* text);

int match_star(char c, const char* regexp, const char* text) {
    do {
        if (match_here(regexp, text)) return 1;
    } while (*text != '�' && (*text++ == c || c == '.'));
    return 0;
}

int match_here(const char* regexp, const char* text) {
    if (regexp[0] == '�') return 1;
    if (regexp[1] == '*') return match_star(regexp[0], regexp + 2, text);
    if (regexp[0] == '$' && regexp[1] == '�') return *text == '�';
    if (*text != '�' && (regexp[0] == '.' || regexp[0] == *text)) {
        return match_here(regexp + 1, text + 1);
    }
    return 0;
}

int match(const char* regexp, const char* text) {
    if (regexp[0] == '^') return match_here(regexp + 1, text);
    do {
        if (match_here(regexp, text)) return 1;
    } while (*text++ != '�');
    return 0;
}

int main(void) {
    printf("Match 'a*b' in 'aaab': %d
", match("a*b", "aaab"));
    printf("Match '^c.t' in 'cat': %d
", match("^c.t", "cat"));
    printf("Match '^c.t' in 'dog': %d
", match("^c.t", "dog"));
    return 0;
}

